//! AG-2D-01 Breakout fidelity contract tests (PLAN-829 T-04).
//!
//! The heavy case is `golden_trace_replay_matches_reference`: it loads the
//! FROZEN independent reference trace (`testdata/breakout/golden_trace.json`,
//! generated by `gen_golden_trace.py` from the frozen breakout.rs) and
//! replays the FROZEN action stream through the Rust implementation,
//! asserting positions within the manifest tolerance (1e-3) and
//! score/contact/sound/bounce-side equality exactly.

use agp::core::runtime::Runtime;
use agp::games::breakout::*;
use serde::Deserialize;
use std::path::PathBuf;
use std::time::Duration;

const POS_TOL: f32 = 1.0e-3;

fn trace_path() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("testdata/breakout/golden_trace.json")
}

#[derive(Debug, Deserialize)]
struct TraceTick {
    t: u64,
    bx: f32,
    by: f32,
    px: f32,
    score: u32,
    contacts: u32,
    sounds: u64,
}

#[derive(Debug, Deserialize)]
struct TraceContact {
    t: u64,
    kind: String,
    side: String,
    brick: Option<u8>,
}

#[derive(Debug, Deserialize)]
struct GoldenTrace {
    ticks: Vec<TraceTick>,
    actions: Vec<i8>,
    contacts_detail: Vec<TraceContact>,
}

fn load_trace() -> GoldenTrace {
    let bytes = std::fs::read(trace_path()).expect("golden trace must exist (frozen in testdata)");
    serde_json::from_slice(&bytes).expect("golden trace parses")
}

fn kind_str(k: ColliderKind) -> &'static str {
    match k {
        ColliderKind::WallLeft => "wall_left",
        ColliderKind::WallRight => "wall_right",
        ColliderKind::WallBottom => "wall_bottom",
        ColliderKind::WallTop => "wall_top",
        ColliderKind::Paddle => "paddle",
        ColliderKind::Brick(_) => "brick",
    }
}

fn side_str(s: Side) -> &'static str {
    match s {
        Side::Left => "L",
        Side::Right => "R",
        Side::Top => "T",
        Side::Bottom => "B",
    }
}

/// Run the sim on a frozen action encoding (-1/0/1) and return per-tick
/// observations plus the exact contact-detail sequence.
fn run_trace(actions: &[i8]) -> (Vec<(u64, f32, f32, f32, u32, u32, u64)>, Vec<TraceContact>) {
    let mut rt = Runtime::new(Duration::from_nanos(16_666_667), 0x8293_D01);
    let mut driver = BreakoutDriver::default();
    let mut per_tick = Vec::with_capacity(actions.len());
    let mut details = Vec::new();
    let mut cumulative_sounds = 0u64; // reference `sounds` is cumulative per tick
    for (t, a) in actions.iter().enumerate() {
        let dir = match a {
            -1 => PaddleDir::Left,
            1 => PaddleDir::Right,
            _ => PaddleDir::None,
        };
        let events = rt.step(&mut driver, vec![BreakoutAction::Paddle(dir)]);
        let mut contacts = 0u32;
        for e in &events {
            match e.payload {
                BreakoutEvent::Contact { kind, side } => {
                    contacts += 1;
                    details.push(TraceContact {
                        t: t as u64,
                        kind: kind_str(kind).to_string(),
                        side: side_str(side).to_string(),
                        brick: match kind {
                            ColliderKind::Brick(i) => Some(i),
                            _ => None,
                        },
                    });
                }
                BreakoutEvent::Sound { total } => {
                    cumulative_sounds = total;
                }
                BreakoutEvent::BrickGone { .. } => {}
            }
        }
        per_tick.push((
            t as u64,
            driver.ball_pos[0],
            driver.ball_pos[1],
            driver.paddle_x,
            driver.score,
            contacts,
            cumulative_sounds,
        ));
    }
    (per_tick, details)
}

