#[test]
fn layout_matches_frozen_source() {
    let bricks = brick_grid();
    assert_eq!(bricks.len(), 56, "7 rows x 8 cols");
    assert_eq!(bricks[0], [-367.5, 45.0], "first brick center");
    assert_eq!(bricks[1], [-262.5, 45.0], "brick step x = 105");
    assert_eq!(bricks[8], [-367.5, 80.0], "brick step y = 35");
    assert_eq!(paddle_y(), -240.0);
    assert_eq!(paddle_clamp(), (-375.0, 375.0));
    let (_, paddle_half) = (walls()[0], walls()[0].1);
    assert_eq!(paddle_half, [5.0, 305.0], "side wall half-size");
    assert_eq!(walls()[2].1, [455.0, 5.0], "bottom wall half-size");
}

#[test]
fn initial_ball_velocity_matches_source() {
    let v = initial_ball_velocity();
    let speed = (v[0] * v[0] + v[1] * v[1]).sqrt();
    assert!((speed - BALL_SPEED).abs() <= 1e-3, "|v| must be 400");
    // direction (0.5, -0.5)/|.| : components equal magnitude, vy negative
    assert!(
        (v[0] - 282.84272).abs() < 1e-2,
        "vx ≈ 282.8427, got {}",
        v[0]
    );
    assert!(
        (v[1] + 282.84272).abs() < 1e-2,
        "vy ≈ -282.8427, got {}",
        v[1]
    );
}

#[test]
fn collision_side_classification_matches_source() {
    let r = 15.0f32;
    // Ball left of the box, overlapping: side Left.
    assert_eq!(
        circle_aabb_side([-54.0, 0.0], r, [0.0, 0.0], [50.0, 15.0]),
        Some(Side::Left)
    );
    // Ball right of the box: side Right.
    assert_eq!(
        circle_aabb_side([54.0, 0.0], r, [0.0, 0.0], [50.0, 15.0]),
        Some(Side::Right)
    );
    // Ball above (y greater): Top.
    assert_eq!(
        circle_aabb_side([0.0, 20.0], r, [0.0, 0.0], [50.0, 15.0]),
        Some(Side::Top)
    );
    // Ball below: Bottom.
    assert_eq!(
        circle_aabb_side([0.0, -20.0], r, [0.0, 0.0], [50.0, 15.0]),
        Some(Side::Bottom)
    );
    // Center inside the box (offset == 0): Bottom per the source's
    // `else if offset.y > 0` branch.
    assert_eq!(
        circle_aabb_side([0.0, 0.0], r, [0.0, 0.0], [50.0, 15.0]),
        Some(Side::Bottom)
    );
    // No overlap.
    assert_eq!(
        circle_aabb_side([-70.0, 0.0], r, [0.0, 0.0], [50.0, 15.0]),
        None
    );
}

#[test]
fn reflection_is_conditional_on_velocity_direction() {
    // Left contact with vx > 0 → flips.
    let mut v = [100.0f32, 0.0];
    reflect(&mut v, Side::Left);
    assert_eq!(v[0], -100.0);
    // Left contact with vx < 0 → NO flip (prevents sticking).
    let mut v = [-100.0f32, 0.0];
    reflect(&mut v, Side::Left);
    assert_eq!(v[0], -100.0);
    // Bottom with vy > 0 → flips (bottom-wall bounce exists in the sample).
    let mut v = [0.0f32, 100.0];
    reflect(&mut v, Side::Bottom);
    assert_eq!(v[1], -100.0);
    // Top with vy > 0 → no flip.
    let mut v = [0.0f32, 100.0];
    reflect(&mut v, Side::Top);
    assert_eq!(v[1], 100.0);
}

// ---------------------------------------------------------------------------
// Golden-trace fidelity (the V-03 fidelity evidence, test-side)
// ---------------------------------------------------------------------------

#[test]
fn golden_trace_replay_matches_reference() {
    let trace = load_trace();
    assert_eq!(trace.ticks.len(), trace.actions.len());

    let (per_tick, details) = run_trace(&trace.actions);

    let mut max_pos_diff = 0.0f32;
    for (got, want) in per_tick.iter().zip(trace.ticks.iter()) {
        let (t, bx, by, px, score, contacts, sounds) = *got;
        assert_eq!(t, want.t);
        max_pos_diff = max_pos_diff
            .max((bx - want.bx).abs())
            .max((by - want.by).abs())
            .max((px - want.px).abs());
        assert!(
            (bx - want.bx).abs() <= POS_TOL,
            "tick {t}: bx {} vs {}",
            bx,
            want.bx
        );
        assert!(
            (by - want.by).abs() <= POS_TOL,
            "tick {t}: by {} vs {}",
            by,
            want.by
        );
        assert!(
            (px - want.px).abs() <= POS_TOL,
            "tick {t}: px {} vs {}",
            px,
            want.px
        );
        assert_eq!(score, want.score, "tick {t}: score diverged");
        assert_eq!(contacts, want.contacts, "tick {t}: contact count diverged");
        assert_eq!(sounds, want.sounds, "tick {t}: cumulative sounds diverged");
    }

    // Exact contact sequence: kind, side, brick index, per tick order.
    assert_eq!(details.len(), trace.contacts_detail.len(), "contact count");
    for (got, want) in details.iter().zip(trace.contacts_detail.iter()) {
        assert_eq!(got.t, want.t, "contact tick");
        assert_eq!(got.kind, want.kind, "contact kind @{}", want.t);
        assert_eq!(got.side, want.side, "contact side @{}", want.t);
        assert_eq!(got.brick, want.brick, "contact brick @{}", want.t);
    }

    // The reference run must exercise every collider family (its generator
    // asserts this too — belt and braces against a degenerate trace).
    for k in [
        "paddle",
        "brick",
        "wall_left",
        "wall_right",
        "wall_top",
        "wall_bottom",
    ] {
        assert!(
            details.iter().any(|c| c.kind == k),
            "trace must contain {k} contacts"
        );
    }
    eprintln!(
        "golden trace: {} ticks, max pos diff {max_pos_diff:e}",
        per_tick.len()
    );
}

#[test]
fn scoring_matches_source_semantics() {
    let trace = load_trace();
    let (per_tick, _) = run_trace(&trace.actions);
    let mut last = 0u32;
    let mut destroyed = 0u32;
    for (t, _, _, _, score, contacts, _) in &per_tick {
        assert!(*score >= last, "score monotonic @tick {t}");
        assert!(
            *score - last <= (*contacts).into() || *contacts > 0,
            "score jump sane @tick {t}"
        );
        destroyed += *score - last;
        last = *score;
    }
    // +1 per brick contact; the frozen run destroys all 56 bricks.
    assert_eq!(destroyed, 56);
    assert_eq!(last, 56);
}

#[test]
fn sound_count_equals_contact_count_every_tick() {
    let trace = load_trace();
    let (per_tick, details) = run_trace(&trace.actions);
    let total_contacts: u32 = per_tick.iter().map(|p| p.5).sum();
    assert_eq!(total_contacts as usize, details.len());
    // Cumulative sounds at the final tick == total contacts (1:1 trigger).
    let final_sounds = per_tick.last().unwrap().6;
    assert_eq!(final_sounds, total_contacts as u64);
}

#[test]
fn bottom_wall_bounces_and_no_ball_loss_exists() {
    // The frozen sample has NO ball loss: run a scripted stream where the
    // paddle idles (actions all 0) — the ball must bounce off the bottom wall
    // forever and never leave the arena.
    let actions = vec![0i8; 3000];
    let (per_tick, details) = run_trace(&actions);
    assert!(
        details.iter().any(|c| c.kind == "wall_bottom"),
        "bottom wall must bounce the ball"
    );
    for (_, bx, by, _, _, _, _) in &per_tick {
        assert!(
            *by > BOTTOM_WALL - BALL_DIAMETER && *by < TOP_WALL + BALL_DIAMETER,
            "ball must stay in the arena (no ball-loss semantics): by={by}"
        );
        assert!(
            *bx > LEFT_WALL - BALL_DIAMETER && *bx < RIGHT_WALL + BALL_DIAMETER,
            "ball x must stay in the arena: bx={bx}"
        );
    }
    // No failure/life events exist in the event enum at all (compile-time
    // proof: BreakoutEvent has no GameOver/LifeLost variant).
}

#[test]
fn paddle_clamp_matches_source_bounds() {
    let actions = vec![1i8; 600]; // hold right: must clamp at +390
    let (per_tick, _) = run_trace(&actions);
    for (_, _, _, px, _, _, _) in &per_tick {
        assert!(
            *px <= 375.0 + 1e-6 && *px >= -375.0 - 1e-6,
            "paddle in bounds: {px}"
        );
    }
    assert!(
        (per_tick.last().unwrap().3 - 375.0).abs() < 1e-3,
        "clamped at 375"
    );
}

#[test]
fn scene_tracks_brick_destruction_via_deltas() {
    let trace = load_trace();
    let mut rt = Runtime::new(Duration::from_nanos(16_666_667), 0x8293_D01);
    let mut driver = BreakoutDriver::default();
    for a in &trace.actions {
        let dir = match a {
            -1 => PaddleDir::Left,
            1 => PaddleDir::Right,
            _ => PaddleDir::None,
        };
        let _ = rt.step(&mut driver, vec![BreakoutAction::Paddle(dir)]);
    }
    // 4 walls + paddle + ball remain; all 56 bricks were destroyed.
    assert_eq!(rt.scene().live_count(), 6);
    assert_eq!(driver.score, 56);
    // The change log length is sane: spawn batch (62) + per-tick deltas.
    assert!(rt.log().len() > trace.actions.len());
}

/// Guard against a vacuous golden trace (e.g. someone truncates the file).
#[test]
fn golden_trace_is_rich_not_vacuous() {
    let trace = load_trace();
    assert!(
        trace.ticks.len() >= 10_000,
        "trace must cover real gameplay"
    );
    assert!(
        trace.contacts_detail.len() > 100,
        "trace must contain contacts"
    );
    assert_eq!(
        trace.ticks.last().unwrap().score,
        56,
        "frozen reference destroys all 56 bricks"
    );
}
